B.QI=new A.dF("rabbit","RABBIT EARS",15,1.13,0.8,"Bent coat hanger. Somehow it works.")
B.QF=new A.dF("dipole","DIPOLE ARRAY",140,1.13,5.4,"Roof-mounted. Hums in the rain.")
B.QA=new A.dF("vhf","VHF MAST",1300,1.14,34,"Red beacon. Nobody climbs it twice.")
B.QH=new A.dF("relay","MICROWAVE RELAY",12e3,1.14,215,"Line of sight to the next dead town.")
B.QB=new A.dF("head","CABLE HEADEND",11e4,1.15,1400,"Copper into every living room.")
B.QD=new A.dF("sat","SATELLITE UPLINK",1e6,1.15,9200,"Bounce it off something in orbit.")
